from pathlib import Path
import re

# Add the pre-class briefing reference data to the protected public config.
p = Path('sim03/lib/scenario.js')
s = p.read_text()
needle = """    annualBudget: 9,\n    runMinimum: 3,\n    lineMaximum: 3,\n    coldOpen: [\n"""
replacement = """    annualBudget: 9,\n    runMinimum: 3,\n    lineMaximum: 3,\n    briefing: {\n      title: 'Midland Equipment — Briefing & exhibits',\n      note: 'Reference copy of the pre-class packet. It is collapsed by default so the simulation does not reteach the briefing.',\n      company: [\n        'Midland sells and services commercial HVAC systems — the large rooftop units that heat and cool schools, hospitals, and office buildings. The company operates in Ohio, Indiana, and Michigan, and has roughly 4,000 of its units installed in customers’ buildings. Revenue comes from two places: selling equipment, and a service department that bills by the visit. Sixty-two field technicians drive to those buildings all day, every day.',\n        'The company is 41 years old, profitable, and nobody thinks it is in trouble.'\n      ],\n      exhibits: [\n        {\n          title: 'Exhibit 1 — Where the revenue comes from',\n          columns: ['', 'Revenue', 'Gross margin', 'Gross profit'],\n          rows: [\n            ['Equipment sales', '$187M (78%)', '9%', '$16.8M'],\n            ['Service', '$53M (22%)', '34%', '$18.0M']\n          ],\n          note: 'Read those last two numbers again before you move on.'\n        },\n        {\n          title: 'Exhibit 2 — Where last year’s technology money went',\n          body: ['The technology budget is $9 million a year and has not changed in four years.'],\n          columns: ['Line', 'Last year'],\n          rows: [\n            ['Keeping current systems running (the 14-year-old ERP, help desk, licenses)', '$6.1M'],\n            ['Backup and redundancy', '$0.7M'],\n            ['Extra capacity', '$0.4M'],\n            ['Getting data back from units in the field', '$0.2M'],\n            ['New features and visible projects', '$1.6M']\n          ]\n        },\n        {\n          title: 'Exhibit 3 — The service department last year',\n          columns: ['', ''],\n          rows: [\n            ['Service visits', '14,000'],\n            ['Visits where the technician found nothing wrong', '19%'],\n            ['Repeat visits to the same unit within 30 days', '11%'],\n            ['Average cost of sending a truck', '$290']\n          ],\n          note: 'That is roughly 4,200 trips that arguably should not have happened, at something close to $1.2 million.'\n        },\n        {\n          title: 'Exhibit 4 — System outages, last three years',\n          body: ['Eleven unplanned outages, 214 total hours down. Sixty-one percent of those hours fell between June and August. The dispatch system is what technicians use to know where to go.']\n        },\n        {\n          title: 'Exhibit 5 — Customers lost last year',\n          body: ['Two accounts, worth $2.1 million a year in service revenue between them. Both gave the same reason on the way out, and it was not price. It was how long they waited for someone to show up.']\n        },\n        {\n          title: 'Exhibit 6 — What the machines already know',\n          body: [\n            'Every unit Midland has installed since 2016 — about 3,100 of the 4,000 in the field — has a controller that records run hours, temperatures, and fault codes. The data exists today. The only way anyone at Midland can see it is for a technician to drive out and plug a laptop into the unit.',\n            'Trade press, March: Carrolton Systems has been piloting a flat-rate coverage program for commercial customers in Georgia and Tennessee.'\n          ]\n        }\n      ]\n    },\n    coldOpen: [\n"""
if needle not in s:
    raise SystemExit('scenario publicConfig anchor not found')
s = s.replace(needle, replacement, 1)
p.write_text(s)

# Add a collapsed briefing/exhibits panel during both allocation screens and a
# complete, printable decision/outcome record on the final screen.
p = Path('sim03/public/index.html')
s = p.read_text()
css_anchor = ".summary{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:22px}.summary .card{min-height:150px}.mini{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;margin-top:12px}.mini div{border:1px solid var(--line);padding:8px 5px;text-align:center}.mini b{display:block;font:600 17px var(--mono);color:var(--amber)}.mini span{font:8px var(--mono);letter-spacing:.07em;text-transform:uppercase;color:var(--dimmer)}\n"
css_repl = css_anchor + ".briefing{margin:20px 0;border:1px solid var(--line2);background:var(--panel)}.briefing>summary{cursor:pointer;padding:13px 16px;font:11px var(--mono);letter-spacing:.11em;text-transform:uppercase;color:var(--amber);list-style:none}.briefing>summary::-webkit-details-marker{display:none}.briefing>summary:after{content:'+';float:right;color:var(--dim)}.briefing[open]>summary:after{content:'−'}.briefing-body{padding:0 16px 18px;border-top:1px solid var(--line)}.briefing-body>p{margin-top:14px;color:#C9C6BE}.exhibit{margin-top:18px;padding-top:15px;border-top:1px solid var(--line)}.exhibit h3{font:500 15px var(--serif);color:var(--bone);margin-bottom:8px}.exhibit p{color:#C3C0B8;margin:7px 0}.exhibit table{width:100%;border-collapse:collapse;margin-top:9px;font-size:13px}.exhibit th,.exhibit td{border-bottom:1px solid var(--line);padding:7px 8px;text-align:left;vertical-align:top}.exhibit th{font:9px var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--dimmer)}.result-section{margin-top:26px}.result-section>.eyebrow{margin-bottom:10px}.result-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.result-grid .outcome{margin-top:0}.result-grid .card{min-height:0}@media(max-width:760px){.result-grid{grid-template-columns:1fr}}\n"
if css_anchor not in s:
    raise SystemExit('index CSS anchor not found')
s = s.replace(css_anchor, css_repl, 1)

fn_anchor = "function defaultAlloc(){return {run:3,uptime:0,capacity:0,connect:0,features:0}}\nfunction renderAllocation(year){"
fn_repl = """function defaultAlloc(){return {run:3,uptime:0,capacity:0,connect:0,features:0}}\nfunction briefingPanel(){\n  const b=C?.briefing;if(!b)return '';\n  const exhibits=(b.exhibits||[]).map(ex=>{\n    const body=(ex.body||[]).map(x=>`<p>${esc(x)}</p>`).join('');\n    const table=ex.rows?.length?`<table><thead>${ex.columns?.length?`<tr>${ex.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr>`:''}</thead><tbody>${ex.rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table>`:'';\n    return `<section class=\"exhibit\"><h3>${esc(ex.title)}</h3>${body}${table}${ex.note?`<p><em>${esc(ex.note)}</em></p>`:''}</section>`;\n  }).join('');\n  return `<details class=\"briefing\"><summary>Briefing & exhibits</summary><div class=\"briefing-body\"><p class=\"hint\">${esc(b.note||'Reference copy of the pre-class briefing.')}</p>${(b.company||[]).map(x=>`<p>${esc(x)}</p>`).join('')}${exhibits}</div></details>`;\n}\nfunction renderAllocation(year){"""
if fn_anchor not in s:
    raise SystemExit('index function anchor not found')
s = s.replace(fn_anchor, fn_repl, 1)

# Insert the collapsed panel into the non-captain allocation state.
needle = """    <p class=\"lede\">${year===1?'The physical constraint is the point: taking a million for one line means it does not exist somewhere else.':'Your Year 1 choices stay with you. The second allocation is shared by your team.'}</p>\n    ${committed?runningHTML(committed,`Team Year ${year} allocation`):notice(`Waiting for ${captain} to commit Year ${year}.`)}\n"""
repl = """    <p class=\"lede\">${year===1?'The physical constraint is the point: taking a million for one line means it does not exist somewhere else.':'Your Year 1 choices stay with you. The second allocation is shared by your team.'}</p>\n    ${briefingPanel()}\n    ${committed?runningHTML(committed,`Team Year ${year} allocation`):notice(`Waiting for ${captain} to commit Year ${year}.`)}\n"""
if needle not in s:
    raise SystemExit('team allocation panel anchor not found')
s = s.replace(needle, repl, 1)

# Insert the collapsed panel into the normal/captain allocation state.
needle = """  <p class=\"lede\">${year===1?'The physical constraint is the point: taking a million for one line means it does not exist somewhere else.':'Your Year 1 choices stay with you. Allocate the second $9M with the running totals visible.'}</p>\n  ${running?runningHTML(running,'Running totals, including this draft'):''}\n"""
repl = """  <p class=\"lede\">${year===1?'The physical constraint is the point: taking a million for one line means it does not exist somewhere else.':'Your Year 1 choices stay with you. Allocate the second $9M with the running totals visible.'}</p>\n  ${briefingPanel()}\n  ${running?runningHTML(running,'Running totals, including this draft'):''}\n"""
if needle not in s:
    raise SystemExit('normal allocation panel anchor not found')
s = s.replace(needle, repl, 1)

# Replace the post-completion summary with a full results screen.
pat = re.compile(r"  if\(S\.finished\)\{\n.*?\n    return;\n  \}\n  shell\(`", re.S)
match = pat.search(s)
if not match:
    raise SystemExit('finished-results block not found')
full = """  if(S.finished){\n    const y1o=S.allOutcomes?.year1||S.year1Outcome||null;\n    const y2o=S.allOutcomes?.year2||S.year2Outcome||null;\n    const y3o=S.allOutcomes?.year3||null;\n    const cum=y3o?.cumulative||(S.year1&&S.year2?runningTotals(S.year1,S.year2):null);\n    shell(`<div class=\"eyebrow\">Full results</div><h2>Your complete Midland decision record.</h2>\n    <p class=\"lede\">Your choices and every consequence you reached are collected here. Nothing is scored or ranked.</p>\n    <div class=\"result-section\"><div class=\"eyebrow\">What you chose</div>\n      <div class=\"result-grid\">\n        <div class=\"card\"><h3>Your opening view</h3><p>${esc(S.strategicView||'—')}</p></div>\n        <div class=\"card\"><h3>Year 1 allocation</h3>${S.year1?miniAlloc(S.year1):'<p>—</p>'}</div>\n        <div class=\"card\"><h3>Year 2 allocation</h3>${S.year2?miniAlloc(S.year2):'<p>—</p>'}</div>\n        <div class=\"card\"><h3>Cumulative portfolio</h3>${cum?miniAlloc(cum):'<p>—</p>'}</div>\n      </div>\n    </div>\n    <div class=\"result-section\"><div class=\"eyebrow\">What happened</div>\n      ${y1o?`<div class=\"outcome\"><h3>${esc(y1o.title)}</h3><p>${esc(y1o.narrative)}</p></div>`:''}\n      <div class=\"result-grid\" style=\"margin-top:12px\">\n        ${y2o?.heat?`<div class=\"outcome\"><h3>${esc(y2o.heat.title)}</h3><p>${esc(y2o.heat.narrative)}</p></div>`:''}\n        ${y2o?.competitor?`<div class=\"outcome\"><h3>${esc(y2o.competitor.title)}</h3><p>${esc(y2o.competitor.narrative)}</p></div>`:''}\n      </div>\n      ${y3o?`<div class=\"outcome\"><h3>${esc(y3o.title)}</h3><p>${esc(y3o.narrative)}</p></div>`:''}\n    </div>\n    <div class=\"result-section\"><div class=\"eyebrow\">Your reflections</div>\n      <div class=\"card\"><h3>${esc(C.reflectionPrompts[0])}</h3><p style=\"white-space:pre-wrap\">${esc(S.reflection1||'—')}</p></div>\n      <div class=\"card\" style=\"margin-top:12px\"><h3>${esc(C.reflectionPrompts[1])}</h3><p style=\"white-space:pre-wrap\">${esc(S.reflection2||'—')}</p></div>\n    </div>\n    ${notice('Run complete. These full results are ready to screenshot or print to PDF.')}\n    <div class=\"actions\"><button class=\"btn pri\" id=\"printBtn\">Print / save PDF</button></div>`);\n    document.getElementById('printBtn').onclick=()=>window.print();\n    return;\n  }\n  shell(`"""
s = s[:match.start()] + full + s[match.end():]
p.write_text(s)

# Extend the assertion-only build guard so briefing/reference and complete results cannot regress.
p = Path('sim03/build.js')
s = p.read_text()
anchor = """if (index.includes('authored calibration does not yet define')) refuse('Year 3 calibration scaffolding reached the student bundle');\n\nfunction checkScripts(name, source) {\n"""
repl = """if (index.includes('authored calibration does not yet define')) refuse('Year 3 calibration scaffolding reached the student bundle');\nfor (const marker of ['Briefing & exhibits','Full results','Year 2 allocation','Cumulative portfolio','What happened'])\n  if (!index.includes(marker)) refuse('briefing/full-results marker missing: ' + marker);\nfor (const marker of ['Exhibit 1 — Where the revenue comes from','Exhibit 6 — What the machines already know'])\n  if (!S.publicConfig().briefing?.exhibits?.some(x => x.title === marker)) refuse('briefing data missing: ' + marker);\n\nfunction checkScripts(name, source) {\n"""
if anchor not in s:
    raise SystemExit('build guard anchor not found')
s = s.replace(anchor, repl, 1)
p.write_text(s)
